CREATE TABLE `report` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '举报ID',
  `user_id` int NOT NULL COMMENT '举报人ID',
  `dispute_type` tinyint NOT NULL COMMENT '纠纷类型：1异常索赔、2仅退款、3异常退货、4异常评价、5骗取财物、6其它',
